"""Apply intersection-over-union overlap between box_a and box_b
    """
def iou(box_a: Any, box_b: Any, norm: Any) -> object {
    xmin_a = min(box_a[0], box_a[2]);
    ymin_a = min(box_a[1], box_a[3]);
    xmax_a = max(box_a[0], box_a[2]);
    ymax_a = max(box_a[1], box_a[3]);
    xmin_b = min(box_b[0], box_b[2]);
    ymin_b = min(box_b[1], box_b[3]);
    xmax_b = max(box_b[0], box_b[2]);
    ymax_b = max(box_b[1], box_b[3]);
    area_a = (
        ((ymax_a - ymin_a) + (norm == False)) * ((xmax_a - xmin_a) + (norm == False))
    );
    area_b = (
        ((ymax_b - ymin_b) + (norm == False)) * ((xmax_b - xmin_b) + (norm == False))
    );
    if ((area_a <= 0) and (area_b <= 0)) {
        return 0.0;
    }
    xa = max(xmin_a, xmin_b);
    ya = max(ymin_a, ymin_b);
    xb = min(xmax_a, xmax_b);
    yb = min(ymax_a, ymax_b);
    inter_area = (
        max(((xb - xa) + (norm == False)), 0.0)
        * max(((yb - ya) + (norm == False)), 0.0)
    );
    iou_ratio = inter_area / ((area_a + area_b) - inter_area);
    return iou_ratio;
}
